<script lang="ts">
  import type { PlannerData, CardQuote, CardProfile, CardRule } from "$lib/family-types";
  import { onMount } from "svelte";
  import { apiCall } from "$lib/contract";
  import { errMsg } from "$lib/act";
  import { fmt, isoDay } from "$lib/format";
  import { Button } from "$lib/components/ui/button";
  import { Input } from "$lib/components/ui/input";
  import * as Card from "$lib/components/ui/card";
  let data = $state<PlannerData | null>(null);
  let result = $state<CardQuote | null>(null);
  let error = $state(""); let status = $state(""); let busy = $state(false);
  let merchant = $state(""); let category = $state(""); let amount = $state<number | undefined>(); let purchaseDate = $state(isoDay());
  let frequency = $state("once"); let strategy = $state("full"); let targetDate = $state(""); let paymentAmount = $state<number | undefined>();
  let reserve = $state(0); let checkingId = $state(""); let preferredCard = $state(""); let avoidInterest = $state(true); let usePromotion = $state(false); let foreign = $state(false); let notes = $state("");
  let selectedCard = $state(""); let profile = $state<CardProfile>({grace:"unknown",promo_type:"none"});
  let rewardJson = $state("[]"); let restrictionJson = $state("{}");
  let ruleCard = $state(""); let ruleMerchant = $state(""); let ruleCategory = $state("");
  let ruleGrace = $state(true); let rulePromo = $state(false); let ruleCap = $state(false);
  let ruleMax = $state<number | undefined>(); let ruleAvailable = $state<number | undefined>(); let ruleReserve = $state<number | undefined>();
  const inputClass = "h-11 w-full rounded-md border bg-background px-3 focus-visible:outline-2 focus-visible:outline-ring";
  async function act(work:()=>Promise<void>) { busy=true;error="";status="";try{await work();}catch(e){error=errMsg(e);}finally{busy=false;} }
  async function load() { data=(await apiCall<"GET /api/cardplanner">("/api/cardplanner")).data as unknown as PlannerData;checkingId ||= data.checking[0]?.id ?? ""; }
  function chooseProfile() {
    const p=data?.profiles[selectedCard];profile=p ? structuredClone(p) : {grace:"unknown",promo_type:"none",rewards_verified:false,carrying_interest:false};
    rewardJson=JSON.stringify(profile.rewards ?? [],null,2);restrictionJson=JSON.stringify(profile.restrictions ?? {},null,2);result=null;
  }
  function purchase() {return {merchant,category,amount,date:purchaseDate,frequency,strategy,target_date:targetDate,payment_amount:paymentAmount,reserve,checking_id:checkingId,preferred_card:preferredCard,avoid_interest:avoidInterest,use_promotion:usePromotion,foreign,notes};}
  async function compare() {result=null;await act(async()=>{result=(await apiCall<"POST /api/cardplanner/quote">("/api/cardplanner/quote",{method:"POST",body:{data:purchase()}})).data as unknown as CardQuote;});}
  async function saveProfile() {await act(async()=>{await apiCall<"POST /api/cardplanner/profile">("/api/cardplanner/profile",{method:"POST",body:{data:{...profile,card_id:selectedCard,rewards:JSON.parse(rewardJson),restrictions:JSON.parse(restrictionJson)}}});await load();result=null;status="Manual card profile saved. Missing terms remain unknown.";});}
  async function savePurchase(card_id:string) {await act(async()=>{await apiCall<"POST /api/cardplanner/purchase">("/api/cardplanner/purchase",{method:"POST",body:{data:{...purchase(),card_id}}});await load();result=null;status="Planned purchase saved as a future schedule, not an actual transaction.";});}
  async function saveRule(remove=false, existing?:CardRule) {await act(async()=>{await apiCall<"POST /api/cardplanner/rule">("/api/cardplanner/rule",{method:"POST",body:{data:existing ? {...existing,remove} : {card_id:ruleCard,merchant:ruleMerchant,category:ruleCategory,require_grace:ruleGrace,require_promotion:rulePromo,require_cap:ruleCap,max_balance:ruleMax,min_available:ruleAvailable,reserve:ruleReserve,remove}}});await load();result=null;status="Preference rules saved. Safety conditions always take priority.";});}
  onMount(()=>act(load));
</script>
<div class="space-y-5">
  <header><h1 class="text-2xl font-semibold">Smart Card Planner</h1><p class="mt-2 text-muted-foreground">Compare which card to use, when to buy, and how to pay. No issuer benefits or rates are assumed. Every comparison is hypothetical until you explicitly save.</p></header>
  <div class="flex flex-wrap gap-3"><Button class="min-h-11" href="#family" variant="outline">Accounts and payment modes</Button><Button class="min-h-11" href="#spending" variant="outline">Budget &amp; Spending</Button><Button class="min-h-11" href="#recurring" variant="outline">Edit saved purchase schedules</Button><Button class="min-h-11" href="#churning" variant="outline">Recorded reward balances</Button></div>
  {#if error}<p role="alert" class="rounded border border-destructive p-3">{error}</p>{/if}
  {#if status}<p role="status">{status}</p>{/if}
  {#if busy}<p role="status">Working…</p>{/if}
  {#if data}
  <fieldset disabled={busy} class="space-y-5">
  <Card.Root><Card.Header><Card.Title>Plan a purchase</Card.Title><Card.Description>Reserve checks use the selected checking account's existing bills, budgets and card payments. A card purchase becomes a future card liability; checking pays it through the card's statement cycle.</Card.Description></Card.Header><Card.Content>
    <form class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3" onsubmit={e=>{e.preventDefault();void compare();}} oninput={()=>{result=null;}} onchange={()=>{result=null;}}>
      <label>Merchant<Input class="min-h-11" required bind:value={merchant} /></label><label>Budget category<Input class="min-h-11" bind:value={category} placeholder="Existing category name" /></label><label>Purchase amount<Input class="min-h-11" required type="number" min="0.01" step="0.01" bind:value={amount} /></label>
      <label>Proposed purchase date<Input class="min-h-11" required type="date" bind:value={purchaseDate} /></label><label>Frequency<select aria-label="Frequency" class={inputClass} bind:value={frequency}><option value="once">One time</option><option value="monthly">Monthly</option></select></label>
      <label>Checking account<select aria-label="Checking account" class={inputClass} required bind:value={checkingId}><option value="" disabled>Choose checking</option>{#each data.checking as a (a.id)}<option value={a.id}>{a.display_name || a.name}</option>{/each}</select></label>
      <label>Repayment strategy<select aria-label="Repayment strategy" class={inputClass} bind:value={strategy}><option value="existing">Existing card strategy</option><option value="full">Full statement</option><option value="minimum">Minimum</option><option value="fixed">Fixed amount</option><option value="custom">Custom amount</option><option value="target">Pay off by target date (estimate)</option></select></label>
      <label>Fixed/custom payment<Input class="min-h-11" type="number" min="0" step="0.01" bind:value={paymentAmount} /></label><label>Payoff target date<Input class="min-h-11" type="date" bind:value={targetDate} /></label>
      <label>Required checking reserve<Input class="min-h-11" type="number" min="0" step="0.01" bind:value={reserve} /></label><label>Preferred card<select aria-label="Preferred card" class={inputClass} bind:value={preferredCard}><option value="">No preference</option>{#each data.cards as a (a.id)}<option value={a.id}>{a.display_name || a.name}</option>{/each}</select></label><label>Notes<Input class="min-h-11" bind:value={notes} /></label>
      <label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={avoidInterest} />Avoid cards carrying interest-bearing balances</label><label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={usePromotion} />Use verified promotional financing</label><label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={foreign} />Foreign transaction</label>
      <Button class="min-h-11" type="submit">Compare cards and debit</Button><Button class="min-h-11" variant="outline" onclick={()=>{result=null;}}>Discard comparison</Button>
    </form>
  </Card.Content></Card.Root>
  {#if result}
    <section aria-label="Card comparison" class="space-y-4"><h2 class="text-xl font-semibold">{result.recommendation ? `Recommended: ${result.options.find(o=>o.card_id===result?.recommendation)?.name}` : "No verified recommendation yet"}</h2><p>{result.explanation}</p><p class="text-sm text-muted-foreground">{result.notice}</p>
      <p>Estimated safe to spend until next expected paycheck: {result.safe_to_spend_until_paycheck == null ? "unknown — no verified paycheck schedule" : fmt(result.safe_to_spend_until_paycheck)}. This relies on recorded balances and schedules, not guaranteed income.</p>
      <p>Debit comparison: {fmt(result.debit.net_cost)} · projected checking low {fmt(result.debit.low.balance)} · {result.debit.reserve_protected ? "reserve protected" : "reserve at risk"}</p>
      <p>Category actual {fmt(result.budget.actual)} · planned {fmt(result.budget.planned)} · remaining after purchase {result.budget.remaining_after == null ? "budget not set" : fmt(result.budget.remaining_after)}. Actual rewards earned are not inferred from estimates. Record issuer-confirmed reward balances in the existing Cards tools; their transaction-derived earnings are estimates, separate from balances.</p>
      <div class="grid gap-4 lg:grid-cols-2">{#each result.options as option (option.card_id)}<Card.Root><Card.Header><Card.Title>{option.name}</Card.Title><Card.Description>{option.eligible ? "Verified inputs; estimate eligible for comparison" : "Verification or safety conditions need attention"}</Card.Description></Card.Header><Card.Content class="space-y-2">
        {#each option.reasons as reason (reason)}<p class="text-destructive">{reason}</p>{/each}{#each option.warnings as warning (warning)}<p>{warning}</p>{/each}
        <p>Statement close: {option.close || "unknown"} · expected due: {option.due || "unknown"}</p><p>Rewards: {option.rewards.units} {option.rewards.unit} · dollar value {option.rewards.dollars == null ? "unknown" : fmt(option.rewards.dollars)}</p><p>Purchase interest estimate: {option.interest_estimate == null ? "unknown" : fmt(option.interest_estimate)} · fees {fmt(option.fees)}</p><p>Estimated net purchase cost: {option.net_cost == null ? "unknown" : fmt(option.net_cost)} · resulting utilization: {option.utilization == null ? "unknown" : `${option.utilization}%`}</p>
        {#if option.deferred_interest_risk != null}<p>Potential retroactive interest if promotion is missed (estimate): {fmt(option.deferred_interest_risk)}</p>{/if}
        {#if option.cashflow}<p>Checking low before: {fmt(option.cashflow.before_low.balance)} · after: {fmt(option.cashflow.after_low.balance)} on {option.cashflow.after_low.date}</p><details><summary class="min-h-11 cursor-pointer py-3">Future payment obligations</summary>{#each option.cashflow.payment_events as event (event.key)}<p>{event.date} · {fmt(-event.amount)}</p>{/each}</details><details><summary class="min-h-11 cursor-pointer py-3">Daily checking projection</summary><div class="max-h-72 overflow-auto">{#each option.cashflow.days as day, i (day)}<p>{day} · {fmt(option.cashflow.balances[i])}</p>{/each}</div></details>{/if}
        <p class="text-sm">Saving also applies this repayment strategy to the selected card's entire balance, not only this purchase. The schedule can be edited in Recurring.</p><Button class="min-h-11" disabled={!option.eligible} onclick={()=>savePurchase(option.card_id)}>Save planned purchase on {option.name}</Button>
      </Card.Content></Card.Root>{/each}</div>
    </section>
  {/if}
  <Card.Root><Card.Header><Card.Title>Verified payment card profiles</Card.Title><Card.Description>Add your cards in Family Finance Hub first (Apple Card, Prime Visa, IHG, AAdvantage, Best Buy, Sam’s Club or any other). Enter only issuer terms you have actually checked. Blank fields mean unknown; account balances are edited in the Hub.</Card.Description></Card.Header><Card.Content class="space-y-4">
    <label class="block">Card profile<select aria-label="Card profile" class={inputClass} required bind:value={selectedCard} onchange={chooseProfile}><option value="" disabled>Choose a card</option>{#each data.cards as a (a.id)}<option value={a.id}>{a.display_name || a.name} · recorded balance {fmt(a.balance)}</option>{/each}</select></label>
    {#if selectedCard}<form class="space-y-4" onsubmit={e=>{e.preventDefault();void saveProfile();}}>
      <div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {#each ([["credit_limit","Credit limit"],["available_credit","Available credit"],["purchase_apr","Purchase APR (%)"],["foreign_fee","Foreign transaction fee (%)"],["statement_balance","Actual statement balance"],["minimum_payment","Issuer minimum payment"],["promotional_apr","Promotional APR (%)"],["promo_balance","Existing promotional balance"],["promo_minimum","Promotion minimum purchase"],["balance_threshold","Maximum card balance rule"]] as const) as item (item[0])}<label>{item[1]}<Input class="min-h-11" type="number" min="0" step="0.01" bind:value={profile[item[0]]} /></label>{/each}
        {#each ([["closing_day","Statement closing day"],["due_day","Payment due day"]] as const) as item (item[0])}<label>{item[1]}<Input class="min-h-11" type="number" min="1" max="31" bind:value={profile[item[0]]} /></label>{/each}
        {#each ([["last_close","Actual last closing date"],["next_due","Actual statement due date"],["verified_on","Last verification date"],["promo_starts","Promotion starts"],["promo_expires","Promotion deadline"],["promo_payoff_date","Existing promotion payoff plan date"]] as const) as item (item[0])}<label>{item[1]}<Input class="min-h-11" type="date" bind:value={profile[item[0]]} /></label>{/each}
        <label>Grace period<select aria-label="Grace period" class={inputClass} bind:value={profile.grace}><option value="unknown">Unknown — verify first</option><option value="active">Active</option><option value="lost">Lost</option></select></label><label>Promotion type<select aria-label="Promotion type" class={inputClass} bind:value={profile.promo_type}><option value="none">None</option><option value="introductory">Introductory APR</option><option value="deferred">Deferred interest</option></select></label><label>Issuer terms / data source<Input class="min-h-11" bind:value={profile.source} /></label>
      </div>
      <div class="flex flex-wrap gap-4"><label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={profile.carrying_interest} />Currently carrying an interest-bearing balance</label><label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={profile.rewards_verified} />I verified the rewards, including caps and usage</label><label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={profile.promo_verified} />I verified promotion eligibility and terms</label></div>
      <label class="block">Rewards terms (JSON)<textarea class={`${inputClass} min-h-36 py-3 font-mono text-sm`} bind:value={rewardJson}></textarea></label><p class="text-sm">Each term: unit (USD for cashback percentages, otherwise points/miles), rate, optional value (dollars per point/mile), merchant, category, starts, expires, cap (eligible dollars), used (eligible dollars already spent). Use an explicitly verified rate 0 term if the card earns no rewards. No universal point valuation is assumed.</p>
      <label class="block">Card restrictions (JSON)<textarea class={`${inputClass} min-h-24 py-3 font-mono text-sm`} bind:value={restrictionJson}></textarea></label><p class="text-sm">Keys: excluded_merchants (list), excluded_categories (list), domestic_only (true/false). Saving actual statement fields updates Runway's existing manual statement record.</p><Button class="min-h-11" type="submit">Save card profile</Button>
    </form>{/if}
  </Card.Content></Card.Root>
  <Card.Root><Card.Header><Card.Title>Preferred-card spending rules</Card.Title><Card.Description>Merchant and category preferences never override interest, available credit, reserve or verification safeguards. Saving the same merchant/category edits its rule.</Card.Description></Card.Header><Card.Content class="space-y-4"><form class="grid items-end gap-3 sm:grid-cols-2 lg:grid-cols-3" onsubmit={e=>{e.preventDefault();void saveRule();}}>
    <label>Rule merchant<Input class="min-h-11" bind:value={ruleMerchant} /></label><label>Rule category<Input class="min-h-11" bind:value={ruleCategory} /></label><label>Preferred rule card<select aria-label="Preferred rule card" class={inputClass} required bind:value={ruleCard}><option value="" disabled>Choose card</option>{#each data.cards as a (a.id)}<option value={a.id}>{a.display_name || a.name}</option>{/each}</select></label>
    <label>Balance ceiling<Input class="min-h-11" type="number" min="0" step="0.01" bind:value={ruleMax} /></label><label>Available credit after purchase<Input class="min-h-11" type="number" min="0" step="0.01" bind:value={ruleAvailable} /></label><label>Checking reserve for rule<Input class="min-h-11" type="number" min="0" step="0.01" bind:value={ruleReserve} /></label>
    <label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={ruleGrace} />Require active grace period</label><label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={rulePromo} />Require verified active promotion</label><label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={ruleCap} />Require enough category bonus cap</label><Button class="min-h-11" type="submit">Save preference rule</Button>
  </form>{#each data.rules as rule,i (`${rule.merchant}:${rule.category}:${i}`)}<div class="flex flex-wrap items-center gap-3"><span>{rule.merchant || "All merchants"} · {rule.category || "All categories"} → {data.cards.find(a=>a.id===rule.card_id)?.name || "Missing card"}</span><Button class="min-h-11" variant="outline" onclick={()=>{ruleMerchant=rule.merchant||"";ruleCategory=rule.category||"";ruleCard=rule.card_id;ruleGrace=rule.require_grace;rulePromo=rule.require_promotion;ruleCap=rule.require_cap;ruleMax=rule.max_balance;ruleAvailable=rule.min_available;ruleReserve=rule.reserve;}}>Edit rule</Button><Button class="min-h-11" variant="outline" onclick={()=>saveRule(true,rule)}>Remove rule</Button></div>{/each}</Card.Content></Card.Root>
  <Card.Root><Card.Header><Card.Title>Saved planned purchases</Card.Title><Card.Description>Plans are not actual spending or earned rewards. Actual transactions stay in Budget &amp; Spending.</Card.Description></Card.Header><Card.Content>{#each data.purchases as p (p.id)}<div class="my-3 rounded border p-3"><p>{p.date} · {p.merchant} · {fmt(p.amount)} · {p.status}</p>{#if p.schedule_changed}<p>Schedule changed in Recurring; review its current terms there.</p>{/if}{#if p.status === "planned"}<Button class="mt-2 min-h-11" variant="outline" onclick={()=>act(async()=>{await apiCall<"POST /api/cardplanner/purchase/{id}/cancel">(`/api/cardplanner/purchase/${p.id}/cancel`,{method:"POST"});await load();result=null;})}>Cancel future schedule</Button>{/if}</div>{:else}<p>No saved planned purchases.</p>{/each}</Card.Content></Card.Root>
  </fieldset>
  {/if}
</div>
